-- Arbeitsrecht Berufsbildung > Soziale gesellschaftliche Themen > Nachhaltigkeit > Abfallmanagement
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Betrieb Elektronikschrott gemäß gesetzlichen Vorgaben entsorgen?', 2, '[{"text": "Ja", "correct": true, "because": "Kreislaufwirtschaftsgesetz (KrWG) und ElektroG regeln Entsorgung"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Recycling von Hardware Abfall reduzieren?', 2, '[{"text": "Ja", "correct": true, "because": "Recycling vermindert Müllmengen"}, {"text": "Nein", "correct": false, "because": "Reduktion ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Trennung von Abfall in einem IT-Betrieb für die Nachhaltigkeit relevant?', 2, '[{"text": "Ja", "correct": true, "because": "Trennung fördert Wiederverwertung"}, {"text": "Nein", "correct": false, "because": "Wichtig für Nachhaltigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Fachinformatiker im IT-Betrieb über Abfallentsorgungsvorschriften informiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Unterweisung ist Teil der betrieblichen Pflicht"}, {"text": "Nein", "correct": false, "because": "Information ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann unsachgemäßes Abfallmanagement in einem IT-Betrieb zu Umweltstrafen führen?', 2, '[{"text": "Ja", "correct": true, "because": "Verstöße gegen KrWG können sanktioniert werden"}, {"text": "Nein", "correct": false, "because": "Strafen sind möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt das Abfallmanagement in einem IT-Betrieb?', 2, '[{"text": "Kreislaufwirtschaftsgesetz (KrWG)", "correct": true, "because": "KrWG ist die Grundlage für Abfallentsorgung"}, {"text": "ArbSchG", "correct": false, "because": "Regelt Arbeitsschutz"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Abfallmanagements in einem IT-Betrieb?', 3, '[{"text": "Reduzierung und Wiederverwertung von Abfall", "correct": true, "because": "KrWG zielt auf Kreislaufwirtschaft"}, {"text": "Erhöhung der Kosten", "correct": false, "because": "Kein Ziel"}, {"text": "Vermeidung von Recycling", "correct": false, "because": "Recycling wird gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme im Abfallmanagement ist für einen IT-Betrieb besonders wichtig?', 3, '[{"text": "Entsorgung von Elektronikschrott", "correct": true, "because": "IT-Geräte fallen unter ElektroG"}, {"text": "Verbrennung von Papier", "correct": false, "because": "Weniger nachhaltig"}, {"text": "Keine Trennung", "correct": false, "because": "Trennung ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist für das Abfallmanagement in einem IT-Betrieb verantwortlich?', 2, '[{"text": "Der Arbeitgeber", "correct": true, "because": "Verantwortung liegt beim Betrieb"}, {"text": "Die Auszubildenden", "correct": false, "because": "Nicht deren Pflicht"}, {"text": "Die Kunden", "correct": false, "because": "Kunden haben keine Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich durch ein gutes Abfallmanagement in einem IT-Betrieb?', 3, '[{"text": "Kosteneinsparung durch Recycling", "correct": true, "because": "Wiederverwertung reduziert Entsorgungskosten"}, {"text": "Erhöhung der Abfallmenge", "correct": false, "because": "Kein Vorteil"}, {"text": "Weniger Produktivität", "correct": false, "because": "Produktivität bleibt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zum Abfallmanagement in einem IT-Betrieb?', 4, '[{"text": "Trennung von Abfällen", "correct": true, "because": "Fördert Recycling"}, {"text": "Entsorgung von Elektronikschrott", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Keine Wiederverwertung", "correct": false, "because": "Recycling ist Ziel"}, {"text": "Sammlung von Batterien", "correct": true, "because": "Sonderabfallregelung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein gutes Abfallmanagement einem IT-Betrieb?', 3, '[{"text": "Reduzierung der Umweltbelastung", "correct": true, "because": "Weniger Müll schont Ressourcen"}, {"text": "Kosteneinsparung", "correct": true, "because": "Recycling senkt Entsorgungskosten"}, {"text": "Erhöhung der Abfallmenge", "correct": false, "because": "Kein Vorteil"}, {"text": "Verbessertes Image", "correct": true, "because": "Nachhaltigkeit stärkt Reputation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch schlechtes Abfallmanagement in einem IT-Betrieb?', 4, '[{"text": "Umweltverschmutzung", "correct": true, "because": "Unsachgemäße Entsorgung schadet"}, {"text": "Bußgelder", "correct": true, "because": "Verstöße gegen KrWG strafbar"}, {"text": "Geringere Kosten", "correct": false, "because": "Kosten steigen durch Strafen"}, {"text": "Gesundheitsrisiken", "correct": true, "because": "Z. B. durch Sondermüll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Grundlagen regeln das Abfallmanagement in einem IT-Betrieb?', 3, '[{"text": "Kreislaufwirtschaftsgesetz (KrWG)", "correct": true, "because": "Regelt Abfallentsorgung"}, {"text": "Elektro- und Elektronikgerätegesetz (ElektroG)", "correct": true, "because": "Regelt Elektronikschrott"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "Batteriegesetz (BattG)", "correct": true, "because": "Regelt Batterieentsorgung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Abfallarten fallen typischerweise in einem IT-Betrieb an?', 3, '[{"text": "Elektronikschrott", "correct": true, "because": "Alte Hardware"}, {"text": "Batterien", "correct": true, "because": "Stromversorgung"}, {"text": "Lebensmittelabfälle", "correct": false, "because": "Weniger relevant"}, {"text": "Papier", "correct": true, "because": "Büroabfälle"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Abfallmanagement in einem IT-Betrieb muss gesetzlich geregelt sein. b) Recycling ist keine Maßnahme des Abfallmanagements.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gesetzlich ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Elektronikschrott muss in einem IT-Betrieb fachgerecht entsorgt werden. b) Abfalltrennung fördert die Nachhaltigkeit.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Entsorgung und Nachhaltigkeit"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Schlechtes Abfallmanagement kann Bußgelder verursachen. b) Fachinformatiker müssen nicht über Entsorgung informiert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Das ElektroG regelt die Entsorgung von IT-Geräten. b) Abfallmanagement erhöht die Produktivität direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ElektroG ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Gutes Abfallmanagement kann Kosten in einem IT-Betrieb senken. b) Der Arbeitgeber ist für das Abfallmanagement verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Kostensenkung und Verantwortung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

